export const organismPhoto = (name: string): Photo | undefined =>
  PHOTOS[`organisms/${name.toLowerCase().replace(/[^a-z]+/g, "-")}`];

export const photoSource = (p: Photo) => `${p.by}, ${p.site ?? "Unsplash"}${p.license ? `, ${p.license}` : ""}`;

export const creditLine = (p: Photo) => `Photo: ${photoSource(p)}`;
